async function createOptions(){const request=++optionRequest;const project=$('#createProject').value;$('#submitTask').disabled=true;try{const d=await api('/api/create-options?project='+encodeURIComponent(project));if(state.page!=='automation'||request!==optionRequest)return;$('#createType').innerHTML=d.types.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');const task=d.types.find(t=>/^task$/i.test(t.name));if(task)$('#createType').value=task.id;$('#createAssignee').innerHTML='<option value="">Để Jira chọn mặc định</option>'+d.users.map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('');$('#submitTask').disabled=!d.types.length}catch(e){toast(e.message)}}
function setupCreate(){createId=crypto.randomUUID();$('#createProject').value=state.project;const draft=read('hub-draft',null);if(draft){$('#createSummary').value=draft.summary||'';$('#createDescription').value=draft.description||'';$('#createDate').value=draft.duedate||''}const preview=()=>{$('#createPreview').textContent=($('#createSummary').value||'Chưa có tiêu đề')+' · '+$('#createProject').value+' · '+($('#createDate').value||'Chưa có deadline')};$$('[data-template]').forEach(b=>b.onclick=()=>{$$('[data-template]').forEach(x=>x.classList.toggle('active',x===b));const t=b.dataset.template;$('#createSummary').value=t==='Tùy chỉnh'?'':`[${t}] `;$('#createDescription').value=t==='Tùy chỉnh'?'':`Mục tiêu:\n\nYêu cầu ${t}:\n\nĐầu ra cần bàn giao:\n\nTài liệu tham chiếu:\n\nTiêu chí nghiệm thu:`;preview()});$('#createForm').oninput=preview;$('#createProject').onchange=createOptions;$('#saveDraft').onclick=()=>{localStorage.setItem('hub-draft',JSON.stringify({summary:$('#createSummary').value,description:$('#createDescription').value,duedate:$('#createDate').value}));toast('Đã lưu bản nháp trên trình duyệt')};$('#createForm').onsubmit=async e=>{e.preventDefault();const b=$('#submitTask');b.disabled=true;try{const d=await api('/api/create',{project:$('#createProject').value,type:$('#createType').value,summary:$('#createSummary').value,description:$('#createDescription').value,duedate:$('#createDate').value,assignee:$('#createAssignee').value,requestId:createId});$('#createPreview').innerHTML=`Đã tạo <a href="https://tpl-vn.atlassian.net/browse/${encodeURIComponent(d.key)}" target="_blank" rel="noopener">${esc(d.key)} ↗</a>. Có thể xem trên Jira ngay.`;localStorage.removeItem('hub-draft');$('#createSummary').value='';createId=crypto.randomUUID();toast('Đã tạo '+d.key)}catch(e){toast(e.message+' · Nếu mất kết nối, kiểm tra Jira trước khi tạo lại.')}finally{b.disabled=false}};createOptions();preview()}
$('#team').innerHTML='<option value="">Tất cả team</option>'+[...teams,'Chưa phân team'].map(t=>`<option>${t}</option>`).join('');
$('#team').onchange=e=>{state.team=e.target.value;nav();render()};$('#member').onchange=e=>{state.member=[...e.target.selectedOptions].map(o=>o.value).filter(Boolean);render()};$('#project').onchange=e=>{state.project=e.target.value;localStorage.setItem('hub-workspace',JSON.stringify(state.project));state.member=[];state.epic='';state.search='';$('#search').value='';closeInline();render()};$('#search').oninput=e=>{state.search=e.target.value;render()};$('#settingsNav').onclick=()=>go('settings');$('#newTask').onclick=()=>go('automation');$('#refresh').onclick=async()=>{if(window.ParentTracker?.active()){await window.ParentTracker.refresh();return}await load();await window.checkDailyTasks?.('sync')};
$$('[data-period]').forEach(b=>b.onclick=()=>{state.period=b.dataset.period;controls();load()});function shift(n){if(state.period==='week')state.date.setDate(state.date.getDate()+7*n);else if(state.period==='month'){state.date.setDate(1);state.date.setMonth(state.date.getMonth()+n)}else state.date.setFullYear(state.date.getFullYear()+n);controls();load()}$('#prev').onclick=()=>shift(-1);$('#next').onclick=()=>shift(1);$('#today').onclick=()=>{state.date=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Ho_Chi_Minh'}));controls();load()};
window.addEventListener('hashchange',applyRoute);
async function init(){nav();controls();try{const [connection,palette]=await Promise.all([api('/api/connection'),api('/api/palette').catch(e=>{toast('Chưa tải được màu ưu tiên Jira: '+e.message);return {priorities:[]}})]);state.connection=connection;state.teamConfig=await api('/api/team-config');window.guestCampaignKeys=state.teamConfig.campaignKeys||[];for(const team of teams)teamRoster[team]=state.teamConfig.teams[team]||[];teamByAccount.clear();for(const [team,people] of Object.entries(teamRoster))for(const [id] of people)teamByAccount.set(id,team);jiraPriorities=palette.priorities;$('#profileName').textContent='Guest · Chỉ xem';$('.profile small').textContent='Dữ liệu Jira được chia sẻ';if(localStorage.getItem('hub-account')!==state.connection.accountId){localStorage.removeItem('hub-subtask-job');localStorage.removeItem('hub-draft');localStorage.setItem('hub-account',state.connection.accountId)}$('#project').value=state.project;applyRoute();await load();void window.checkDailyTasks?.('open');if(!Object.values(teamRoster).some(people=>people.length))$('#notice').textContent='Chủ trang chưa cấu hình thành viên.';}catch(e){$('#sync').textContent='Chưa kết nối';$('.live-label').textContent='Jira chưa kết nối';$('.live').title='Jira chưa kết nối';$('.live').classList.add('is-offline');$('#notice').textContent=e.message;$('#content').innerHTML='<div class="empty">Chưa kết nối được nguồn dữ liệu. Vui lòng thử lại sau.</div>'}}


const plannerEpicCatalog=new Map();
function epicControls(){
 let epics=[...new Map(state.issues.filter(t=>(state.team==='Planner'||inTeamScope(t))&&(!state.project||t.project?.key===state.project)&&t.epic?.key).map(t=>[t.epic.key,t.epic])).values()];
 let complete=true;
 if(state.team==='Planner'){
  const projects=state.project?[state.project]:(state.connection?.projects||[]),key=JSON.stringify([state.connection?.accountId,projects]);let entry=plannerEpicCatalog.get(key);
  if(projects.length&&(!entry||Date.now()-entry.at>300000)){
   entry={at:Date.now(),items:entry?.items||null};plannerEpicCatalog.set(key,entry);if(plannerEpicCatalog.size>8)plannerEpicCatalog.delete(plannerEpicCatalog.keys().next().value);
   (async()=>{const items=[];for(const project of projects){let cursor;const seen=new Set();do{const d=await api('/api/epics?'+new URLSearchParams({project,kind:'epics',...(cursor?{cursor}:{})}));items.push(...d.items.map(e=>({key:e.key,name:e.summary})));cursor=d.cursor;if(cursor&&seen.has(cursor))throw Error('Jira trả trang Epic trùng lặp');seen.add(cursor);if(items.length>10000)throw Error('Danh sách Epic quá lớn')}while(cursor)}entry.items=[...new Map(items.map(e=>[e.key,e])).values()];const activeKey=JSON.stringify([state.connection?.accountId,state.project?[state.project]:(state.connection?.projects||[])]);if(state.team==='Planner'&&key===activeKey){const before=state.epic;epicControls();syncFilterButtons();if(before!==state.epic)render()}})().catch(e=>{entry.at=Date.now()-270000;toast('Chưa tải đủ danh sách Epic: '+e.message)});
  }
  complete=!!entry?.items;
  if(complete)epics=entry.items;
 }
 epics.sort((a,b)=>a.name.localeCompare(b.name,'vi'));
 if(complete&&state.epic&&!epics.some(e=>e.key===state.epic))state.epic='';
 if(!complete&&state.epic&&!epics.some(e=>e.key===state.epic))epics.push({key:state.epic,name:state.epic});
 $('#epic').innerHTML='<option value="">Mọi Epic</option>'+epics.map(e=>'<option value="'+esc(e.key)+'">'+esc(e.name)+'</option>').join('');$('#epic').value=state.epic;
}
$('#epic').onchange=e=>{state.epic=e.target.value;render()};
function setSearchOpen(open){$('#searchControl').classList.toggle('open',open);$('#searchToggle').setAttribute('aria-expanded',String(open));$('#searchToggle').setAttribute('aria-label',open?'Đóng tìm kiếm':'Mở tìm kiếm');$('#search').inert=!open;$('#search').tabIndex=open?0:-1;if(open)$('#search').focus();else{state.search='';$('#search').value='';render();$('#searchToggle').focus()}}
$('#searchToggle').onclick=()=>setSearchOpen(!$('#searchControl').classList.contains('open'));
$('#search').onkeydown=e=>{if(e.key==='Escape')setSearchOpen(false)};

function reporterControls(){
 const select=document.getElementById('reporter');if(!select)return;
 const roster=teamRoster.Planner||[];
 if(state.reporter&&!roster.some(([id])=>id===state.reporter))state.reporter='';
 select.hidden=state.team!=='Planner'||state.page!=='calendar';
 select.innerHTML='<option value="">Tất cả Reporter</option>'+roster.map(([id,name])=>'<option value="'+esc(id)+'">'+esc(name)+'</option>').join('');select.value=state.reporter||'';
 select.onchange=e=>{state.reporter=e.target.value;render()};
}
function syncFilterButtons(){
for(const id of ['member','project','epic','reporter']){const select=document.getElementById(id),button=document.getElementById(id+'Filter');if(!button)continue;button.hidden=select.hidden;const label=id==='member'?(state.member.length===0?'Tất cả Assignee':state.member.length===1?select.selectedOptions[0]?.textContent:state.member.length+' Assignee'):(select.selectedOptions[0]?.textContent||select.options[0]?.textContent||'');button.querySelector('span').textContent=label;button.title=label;button.setAttribute('aria-label',select.getAttribute('aria-label')+': '+label)}
}
function openFilterMenu(select,button){
if(inlineBusy)return;if(inlineEditor?.button===button){closeInline();return}closeInline();
const menu=document.createElement('div');menu.id='cardDropdown';menu.className='card-dropdown filter-dropdown'+(button.id==='scaleFilter'?' scale-dropdown':'');menu.setAttribute('role','dialog');menu.setAttribute('aria-label','Lọc '+select.getAttribute('aria-label'));
const multi=select.id==='member';if(multi)menu.classList.add('member-multi-dropdown');const heading=document.createElement('div');heading.className='dropdown-heading';heading.textContent=multi?'Chọn Assignee':select.selectedOptions[0]?.textContent||select.getAttribute('aria-label');
const list=document.createElement('div');list.className='dropdown-options';list.setAttribute('role','menu');menu.append(heading,list);document.body.append(menu);inlineEditor={kind:'filter',button,menu};button.setAttribute('aria-expanded','true');
function populate(){list.replaceChildren();for(const option of [...select.options]){const item=document.createElement('button');item.type='button';item.className='dropdown-option';item.setAttribute('role',multi?'menuitemcheckbox':'menuitemradio');item.setAttribute('aria-checked',String(option.selected));const name=document.createElement('span');name.textContent=option.textContent;const check=document.createElement('span');check.className='dropdown-check';check.textContent=option.selected?'✓':'';item.append(name,check);item.onclick=()=>{if(multi){const index=[...list.children].indexOf(item),scroll=list.scrollTop;state.member=option.value?(state.member.includes(option.value)?state.member.filter(id=>id!==option.value):[...state.member,option.value]):[];render();populate();list.scrollTop=scroll;list.children[index]?.focus();return}select.value=option.value;closeInline();select.dispatchEvent(new Event('change',{bubbles:true}));syncFilterButtons();button.focus()};list.append(item)}if(!list.childElementCount){const empty=document.createElement('p');empty.className='dropdown-empty';empty.textContent='Không tìm thấy kết quả';list.append(empty)}positionDropdown()}
menu.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();closeInline();button.focus()}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const items=[...list.querySelectorAll('button')],index=items.indexOf(document.activeElement);items[(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}else if(e.key==='Tab'){closeInline()}};populate();list.querySelector('[aria-checked="true"]')?.focus();
}
for(const id of ['member','project','epic','reporter']){const select=document.getElementById(id);select.classList.add('filter-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');const button=document.createElement('button');button.id=id+'Filter';button.type='button';button.className='filter-trigger';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','cardDropdown');button.innerHTML='<span></span><svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m3 4.5 3 3 3-3"/></svg>';button.onclick=()=>openFilterMenu(select,button);select.after(button)}
syncFilterButtons();init();

let calendarDraggedKey=null,calendarDateSaving=false,calendarUndoMove=null;
async function moveCalendarTask(key,date){
 const task=state.issues.find(t=>t.key===key);
 if(!task||task.duedate===date||calendarDateSaving||inlineBusy)return;
 calendarDateSaving=true;inlineBusy=true;
 const oldDate=task.duedate;const card=cardFor(key);card?.classList.add('task-date-saving');card?.setAttribute('aria-busy','true');
 try{const saved=await api('/api/issues/'+encodeURIComponent(key)+'/duedate',{duedate:date,expectedDue:oldDate,calendarMove:true},'PUT');task.duedate=saved.duedate;calendarUndoMove={key,from:oldDate,to:saved.duedate};render();toast('Đã đổi deadline '+key+' → '+date.split('-').reverse().join('/')+' trên Jira')}
 catch(e){toast('Chưa đổi deadline: '+e.message)}
 finally{calendarDateSaving=false;inlineBusy=false;card?.classList.remove('task-date-saving');card?.removeAttribute('aria-busy')}
}
function bindCalendarDrag(){return;
 document.getElementById('undoCalendarMove')?.addEventListener('click',undoCalendarMove);
 const clear=()=>{document.querySelectorAll('.day-drop-target,.task-dragging').forEach(el=>el.classList.remove('day-drop-target','task-dragging'))};
 document.querySelectorAll('[data-card]').forEach(card=>{
  card.draggable=true;card.title='Kéo card sang ngày khác để đổi deadline';
  card.querySelectorAll('a,img').forEach(el=>el.draggable=false);
  let interactive=false;
  card.addEventListener('pointerdown',e=>{interactive=!!e.target.closest('button,input,select,a');card.draggable=!interactive});
  card.addEventListener('pointerup',()=>{card.draggable=true});
  card.addEventListener('dragstart',e=>{if(interactive||calendarDateSaving||inlineBusy||state.loading){e.preventDefault();return}closeInline();calendarDraggedKey=card.dataset.card;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',calendarDraggedKey);card.classList.add('task-dragging')});
  card.addEventListener('dragend',()=>{calendarDraggedKey=null;clear()});
 });
 document.querySelectorAll('[data-drop-date]').forEach(day=>{
  day.addEventListener('dragover',e=>{if(!calendarDraggedKey||calendarDateSaving)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.day-drop-target').forEach(el=>{if(el!==day)el.classList.remove('day-drop-target')});day.classList.add('day-drop-target')});
  day.addEventListener('dragleave',e=>{if(!day.contains(e.relatedTarget))day.classList.remove('day-drop-target')});
  day.addEventListener('drop',e=>{if(!calendarDraggedKey)return;e.preventDefault();const key=calendarDraggedKey;calendarDraggedKey=null;clear();moveCalendarTask(key,day.dataset.dropDate)});
 });
}

async function undoCalendarMove(){
 if(!calendarUndoMove||calendarDateSaving||inlineBusy)return;
 const move=calendarUndoMove;calendarDateSaving=true;inlineBusy=true;
 const button=document.getElementById('undoCalendarMove');if(button){button.disabled=true;button.textContent='Đang hoàn tác…'}
 try{const saved=await api('/api/issues/'+encodeURIComponent(move.key)+'/duedate',{duedate:move.from,expectedDue:move.to},'PUT');const task=state.issues.find(t=>t.key===move.key);if(task)task.duedate=saved.duedate;calendarUndoMove=null;render();toast('Đã hoàn tác deadline '+move.key)}
 catch(e){toast('Chưa thể hoàn tác: '+e.message)}
 finally{calendarDateSaving=false;inlineBusy=false;if(button){button.disabled=false;button.textContent='↶ Hoàn tác · '+move.key}}
}

function syncThemeButton(){const select=document.getElementById('theme'),button=document.getElementById('themeFilter');if(select&&button){button.querySelector('span').textContent=select.selectedOptions[0]?.textContent||'';button.setAttribute('aria-label','Chế độ hiển thị: '+button.querySelector('span').textContent)}}
function setupThemeDropdown(){
 const select=document.getElementById('theme');if(!select||document.getElementById('themeFilter'))return;
 select.hidden=true;
 select.classList.add('filter-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');select.setAttribute('aria-label','Chế độ hiển thị');
 const button=document.createElement('button');button.id='themeFilter';button.type='button';button.className='filter-trigger';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','cardDropdown');button.innerHTML='<span></span><svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m3 4.5 3 3 3-3"/></svg>';button.onclick=()=>openFilterMenu(select,button);select.after(button);syncThemeButton();
}

function automation(){return batchAutomation()}

function setupAccentPicker(){
 const input=$('#accentHex'),error=$('#accentError');
 const apply=color=>{prefs.accent=color.toLowerCase();appearance();input.value=color.toUpperCase();input.removeAttribute('aria-invalid');error.textContent='';document.querySelector('.accent-current').style.background=color;$$('[data-accent]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.accent===prefs.accent)))};
 $$('[data-accent]').forEach(b=>b.onclick=()=>apply(b.dataset.accent));
 $('#accentForm').onsubmit=e=>{e.preventDefault();let value=input.value.trim();if(!value.startsWith('#'))value='#'+value;if(/^#[0-9a-f]{3}$/i.test(value))value='#'+[...value.slice(1)].map(c=>c+c).join('');if(!/^#[0-9a-f]{6}$/i.test(value)){error.textContent='Nhập mã HEX hợp lệ, ví dụ #5E6AD2.';input.setAttribute('aria-invalid','true');input.focus();return}apply(value)};
}

function syncScaleButton(){const b=document.getElementById('scaleFilter');if(b){b.querySelector('span').textContent=prefs.scale+'%';b.setAttribute('aria-label','Scale layout: '+prefs.scale+'%')}}
function setupScaleDropdown(){
 const select=document.getElementById('layoutScale');if(!select||document.getElementById('scaleFilter'))return;
 select.hidden=true;select.classList.add('filter-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');
 const button=document.createElement('button');button.id='scaleFilter';button.type='button';button.className='filter-trigger';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','cardDropdown');button.innerHTML='<span></span><svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m3 4.5 3 3 3-3"/></svg>';button.onclick=()=>openFilterMenu(select,button);select.after(button);syncScaleButton();
}

let lastViewMotion='';
function animateViewTransition(){const key=[state.page,state.team,state.period].join(':');if(key===lastViewMotion)return;lastViewMotion=key;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#content').animate([{opacity:.35,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:240,easing:'cubic-bezier(.22,1,.36,1)'})}

